import React, { useState } from "react";
import WeatherCard from "./components/WeatherCard";
import SearchBar from "./components/SearchBar";
import "./App.css";

function App() {
  const [weather, setWeather] = useState(null);

  const fetchWeather = async (city) => {
    try {
      const apiKey = "73f099dc85c1bec48f0cb652b09c91da"; // 🔑 a tua key
      const res = await fetch(
        `https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${apiKey}&units=metric&lang=pt`
      );
      const data = await res.json();
      if (data.cod === 200) {
        setWeather(data);
      } else {
        alert("Cidade não encontrada!");
      }
    } catch (err) {
      console.error(err);
    }
  };

  // folhas em várias cores 🍁
  const leafImages = [
    "https://cdn-icons-png.flaticon.com/512/415/415733.png", // laranja
    "https://cdn-icons-png.flaticon.com/512/415/415734.png", // amarela
    "https://cdn-icons-png.flaticon.com/512/415/415735.png", // vermelha
  ];

  return (
    <div className="App">
      {/* Árvores fixas */}
      <div className="tree left"></div>
      <div className="tree right"></div>

      {/* Folhas animadas 🍂 */}
      {[...Array(20)].map((_, i) => (
        <div
          key={i}
          className="leaf"
          style={{
            left: `${10 + Math.random() * 80}vw`, // caem dentro da largura
            backgroundImage: `url(${leafImages[Math.floor(Math.random() * leafImages.length)]})`,
            animationDuration: `${5 + Math.random() * 5}s`,
            animationDelay: `${Math.random() * 5}s`,
          }}
        ></div>
      ))}

      <h1>Weather App 🌤️</h1>
      <SearchBar onSearch={fetchWeather} />
      {weather && <WeatherCard weather={weather} />}
    </div>
  );
}

export default App;
